<script>
  export let data
  $: schemes = data?.remnawave?.connection_schemes || []
  $: mainNodes = (data?.remnawave?.nodes || []).filter(node => !node.disabled).slice(0, 4)
  $: edges = data?.remnawave?.lte_edges || []
  let activeScheme = 'auto'
  const palette = [['Входная нода','in'],['Транзитная нода','transit'],['CDN','cdn'],['WARP','warp'],['Внешний прокси','proxy'],['Blackhole','block']]
</script>

<section class="page">
  <header><div><span>СХЕМЫ ПОДКЛЮЧЕНИЙ</span><h2>Маршрут виден целиком</h2><p>Проверьте, куда уйдёт трафик при нормальной работе и полном отказе main-нод.</p></div><nav>{#each schemes as scheme}<button class:active={activeScheme===scheme.id} on:click={()=>activeScheme=scheme.id}>{scheme.name.replace(/^\S+\s/,'')}</button>{/each}</nav></header>
  <section class="workspace">
    <aside><small>ПАЛИТРА БЛОКОВ</small><p>Следующий этап редактора позволит собирать и версионировать эти связи.</p>{#each palette as item}<button class={item[1]}><i></i>{item[0]}</button>{/each}<footer>Gateway и Интернет — системные блоки.</footer></aside>
    <div class="board">
      <header><b>{mainNodes.length + edges.length + 3} блоков <i>·</i> {Math.max(1,mainNodes.length + edges.length + 2)} связей</b><span class:bad={mainNodes.some(node=>!node.connected)}>{mainNodes.some(node=>!node.connected)?'Есть недоступные ноды':'Схема готова'}</span></header>
      <div class="canvas">
        <svg viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true"><path class="main" d="M145 250 C230 250 240 250 320 250"/><path class="main" d="M470 250 C560 250 585 105 665 105"/><path class="main" d="M470 250 C560 250 585 210 665 210"/><path class="main" d="M470 250 C560 250 585 315 665 315"/><path class="fallback-line" d="M470 265 C545 330 570 420 665 420"/><path class="fallback-line" d="M815 420 C875 420 870 250 930 250"/><path class="main" d="M815 210 C865 210 870 250 930 250"/></svg>
        <article class="unit gateway" style="left:3%;top:43%"><i>G</i><span><b>Gateway</b><small>клиентский вход</small></span></article>
        <article class="unit selector" style="left:29%;top:43%"><i>↯</i><span><b>Автовыбор</b><small>leastLoad · main only</small></span></article>
        {#each mainNodes as node,index}<article class:off={!node.connected} class="unit node" style={`left:65%;top:${8+index*21}%`}><i>{node.country_code||'—'}</i><span><b>{node.name}</b><small>{node.users_online||0} онлайн</small></span><em>{node.connected?'OK':'OFF'}</em></article>{/each}
        <article class="unit fallback" style="left:65%;top:82%"><i>CDN</i><span><b>Скрытый fallback</b><small>{edges.map(edge=>edge.country_code).join(' + ')||'DE + NL'}</small></span></article>
        <article class="unit internet" style="left:88%;top:43%"><i>↗</i><span><b>Интернет</b><small>egress</small></span></article>
      </div>
      <footer><i></i><span><b>Проверка схемы</b><small>{mainNodes.some(node=>!node.connected)?'Недоступные ноды исключаются из main. CDN остаётся резервом.':'Связи валидны, CDN не расходуется при доступных main-нодах.'}</small></span><em>{activeScheme}</em></footer>
    </div>
  </section>
  <div class="principles"><article><b>Вход</b><span>Подписка и выбранный профиль</span></article><article><b>Маршрут</b><span>Main-ноды, проверки и fallback</span></article><article><b>Выход</b><span>Напрямую, через CDN или WARP</span></article></div>
</section>

