111a;background-image:radial-gradient(#213445 1px,transparent 1px);background-size:16px 16px}.canvas svg{position:absolute;inset:0;width:100%;height:100%}.canvas path{fill:none;stroke:#29b8a9;stroke-width:2;stroke-dasharray:7 6;vector-effect:non-scaling-stroke}.canvas path.fallback-line{stroke:#8d71df}.unit{position:absolute;box-sizing:border-box;width:150px;min-height:55px;display:flex;align-items:center;gap:9px;padding:9px 10px;border:1px solid #2c4152;border-radius:13px;background:#111c28;transform:translate(-50%,-50%);box-shadow:0 10px 24px #0005}.unit>i{display:grid;min-width:34px;height:34px;place-items:center;border-radius:9px;background:#15394a;color:#73d6f5;font-size:10px;font-style:normal;font-weight:900}.unit span{display:grid;min-width:0}.unit b,.unit small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.unit b{font-size:11px}.unit small{color:#6e879a;font-size:9px}.unit em{margin-left:auto;color:#69d9aa;font-size:8px;font-style:normal}.unit.off{border-color:#63353d}.unit.off em{color:#ff8e9a}.unit.gateway>i{background:#39243a;color:#ef9fe8}.unit.selector>i{background:#164035;color:#73dfb5}.unit.fallback>i{background:#322958;color:#b5a2ff}.unit.internet>i{background:#12394a;color:#78d9f0}.board>footer{display:flex;align-items:center;gap:10px;padding:0 16px;border-top:1px solid #1d2b39}.board>footer>i{width:9px;height:9px;border-radius:50%;background:#61d8a5}.board>footer span{display:grid;flex:1}.board>footer small{color:#6f8497;font-size:9px}.board>footer em{color:#80c9f4;font-size:9px;font-style:normal}.principles{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #182532;border-bottom:1px solid #182532}.principles article{display:grid;gap:5px;padding:19px}.principles article+article{border-left:1px solid #182532}.principles span{color:#708699;font-size:11px}@media(max-width:1000px){.page>header{align-items:stretch;flex-direction:column}.page>header nav{max-width:100%}.workspace{grid-template-columns:1fr}.workspace>aside{display:none}.unit{width:135px}.principles{grid-template-columns:1fr}.principles article+article{border-top:1px solid #182532;border-left:0}}@media(max-width:700px){.canvas{min-height:620px}.unit.node{left:66%!important}.unit.internet{left:80%!important;top:93%!important}.canvas svg{display:none}}
</style>
